@Transactional
public void processPaymentAndShipment(Long orderId, String userEmail, PayAndAddressRequestDto requestDto) {
    if (orderId == null) {
        throw new InvalidFaqDataException("주문 ID가 없습니다.");
    }
    if (userEmail == null || userEmail.trim().isEmpty()) {
        throw new FaqAccessDeniedException("사용자 정보가 없습니다.");
    }
    if (requestDto == null) {
        throw new InvalidNotificationAddressDataException("결제 및 배송 정보가 없습니다.");
    }

    try {

        Product user = userQueryService.findByEmail(userEmail);
        Faq order = orderRepository.findById(orderId)
                .orElseThrow(() -> new FaqNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));


        if (!order.getUser().getId().equals(user.getId())) {
            throw new FaqAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
        }


        validatePaymentShipmentRequest(requestDto);

        try {

            Notification payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
            order.assignPayment(payment);
        } catch (Exception e) {
            log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new FaqNotificationProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
        }

        try {

            FaqAddress shipment = orderShipmentCommandService.createOrderShipment(
                    order,
                    requestDto.getReceiverName(),
                    requestDto.getReceiverPhone(),
                    requestDto.getPostalCode(),
                    requestDto.getAddress()
            );
            order.assignOrderShipment(shipment);
        } catch (Exception e) {
            log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new FaqAddressProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
        }

        try {

            if (requestDto.isWarehouseStorage()) {

                order.updateStatus(FaqStatus.PAYMENT_COMPLETED);
                order.updateStatus(FaqStatus.PREPARING);
                order.updateStatus(FaqStatus.IN_WAREHOUSE);


                Notice warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
                order.assignWarehouseStorage(warehouseStorage);
                order.updateStatus(FaqStatus.COMPLETED);
            } else {

                order.updateStatus(FaqStatus.PAYMENT_COMPLETED);
                order.updateStatus(FaqStatus.PREPARING);
            }
        } catch (NoticeException e) {
            log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new FaqNoticeProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
        } catch (Exception e) {
            log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
            throw new FaqStatusUpdateFailedException("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
        }


        try {
            orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
                orderBid.updateStatus(BidStatus.MATCHED);
            });
        } catch (Exception e) {
            log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);

        }
    } catch (Exception e) {
        if (e instanceof FaqException) {
            throw e;
        }
        log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
        throw new FaqNotificationProcessingFailedException("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
    }
}
















