    private void validatePaymentShipmentRequest(PayAndAddressRequestDto requestDto) {
        if (requestDto.getPaymentRequest() == null) {
            throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
        }

        if (requestDto.getReceiverName() == null || requestDto.getReceiverName().trim().isEmpty()) {
            throw new InvalidNotificationAddressDataException("수령인 이름이 없습니다.");
        }

        if (requestDto.getReceiverPhone() == null || requestDto.getReceiverPhone().trim().isEmpty()) {
            throw new InvalidNotificationAddressDataException("수령인 전화번호가 없습니다.");
        }

        if (requestDto.getPostalCode() == null || requestDto.getPostalCode().trim().isEmpty()) {
            throw new InvalidNotificationAddressDataException("우편번호가 없습니다.");
        }

        if (requestDto.getAddress() == null || requestDto.getAddress().trim().isEmpty()) {
            throw new InvalidNotificationAddressDataException("주소가 없습니다.");
        }
    }
